    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
}

.product-info {
    padding: var(--spacing-md);
}

.product-name {
    font-size: 1.1rem;
    font-weight: 600;
    margin-bottom: 0.25rem;
    color: var(--color-primary);
}

.product-category {
    font-size: 0.85rem;
    color: var(--color-text-light);
    margin-bottom: var(--spacing-sm);
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.product-rating {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: var(--spacing-sm);
}

.stars {
    color: #ffd700;
    font-size: 0.9rem;
}

.reviews {
    font-size: 0.85rem;
    color: var(--color-text-light);
}

.product-price {
    display: flex;
    gap: var(--spacing-sm);
    align-items: center;
    margin-bottom: var(--spacing-md);
}

.price-current {
    font-size: 1.5rem;
    font-weight: 700;
    color: var(--color-accent);
}

.price-original {
    font-size: 1rem;
    color: var(--color-text-light);
    text-decoration: line-through;
}

.btn-add-cart {
    width: 100%;
}

/* Deals Section */
.deals-section {
    padding: var(--spacing-xl) var(--spacing-lg);
    background-color: var(--color-bg-light);
}

.deals-grid {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr;
    gap: var(--spacing-lg);
}

.deal-card {
    background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-secondary) 100%);
    color: white;
    padding: var(--spacing-lg);
    border-radius: var(--radius-lg);
    display: flex;
    align-items: flex-end;
    min-height: 250px;
    position: relative;
    overflow: hidden;
    transition: var(--transition);
}

.deal-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 12px 24px rgba(0, 0, 0, 0.2);
}

.deal-card.large {
    min-height: 300px;
}

.deal-card::before {
    content: '';
    position: absolute;
    top: -50%;
    right: -10%;
    width: 300px;
    height: 300px;
    background: radial-gradient(circle, rgba(255, 107, 53, 0.15) 0%, transparent 70%);
    border-radius: 50%;
}

.deal-content {
    position: relative;
    z-index: 1;
    width: 100%;
}

.deal-tag {
    display: inline-block;
    background-color: var(--color-accent);
    color: white;
    padding: 0.25rem 0.75rem;
    border-radius: var(--radius-sm);
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    margin-bottom: var(--spacing-sm);
}

.deal-card h3 {
    font-size: 1.75rem;
    margin-bottom: 0.5rem;
    font-weight: 700;
}

.deal-discount {
    font-size: 1.5rem;
    margin-bottom: var(--spacing-sm);
    font-weight: 600;
}

.deal-ends {
    font-size: 0.9rem;
    opacity: 0.9;
    margin-bottom: var(--spacing-md);
}

/* Editorial Section */
.editorial-section {
    padding: var(--spacing-xl) var(--spacing-lg);
    background-color: var(--color-bg);
}

.editorial-grid {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr;
    gap: var(--spacing-lg);
}

.editorial-card {
    background-color: var(--color-bg-light);
    border-radius: var(--radius-lg);
    overflow: hidden;
    transition: var(--transition);
    cursor: pointer;
    display: flex;
    flex-direction: column;
}

.editorial-card:hover {
    box-shadow: 0 12px 24px rgba(0, 0, 0, 0.1);
    transform: translateY(-4px);
}

.editorial-card.large {
    grid-row: span 1;
}

.editorial-image {
    position: relative;
    overflow: hidden;
    aspect-ratio: 16 / 10;
}

.editorial-card.large .editorial-image {
    aspect-ratio: 2 / 1;
}

.editorial-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: var(--transition);
}

.editorial-card:hover .editorial-image img {
    transform: scale(1.05);
}

.editorial-content {
    padding: var(--spacing-md);
    flex: 1;
    display: flex;
    flex-direction: column;
}

.editorial-tag {
    display: inline-block;
    background-color: var(--color-accent);
    color: white;
    padding: 0.25rem 0.75rem;
    border-radius: var(--radius-sm);
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    margin-bottom: var(--spacing-sm);
    align-self: flex-start;
    width: fit-content;
}

.editorial-title {
    font-size: 1.25rem;
    font-weight: 700;
    margin-bottom: var(--spacing-sm);
    color: var(--color-primary);
}

.editorial-excerpt {
    color: var(--color-text-light);
    font-size: 0.95rem;
    margin-bottom: var(--spacing-md);
    flex: 1;
}

.link-read-more {
    color: var(--color-accent);
    text-decoration: none;
    font-weight: 600;
    transition: var(--transition);
    align-self: flex-start;
}

.link-read-more:hover {
    color: var(--color-accent-light);
    transform: translateX(4px);
}

/* Newsletter Section */
.newsletter-section {
    padding: var(--spacing-xl) var(--spacing-lg);
    background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-secondary) 100%);
    color: white;
    text-align: center;
}

.newsletter-content h2 {
    font-size: 2rem;
    margin-bottom: var(--spacing-sm);
    font-weight: 700;
}

.newsletter-content p {
    font-size: 1.1rem;
    margin-bottom: var(--spacing-lg);
    opacity: 0.9;
}

.newsletter-form {
    display: flex;
    gap: var(--spacing-sm);
    max-width: 500px;
    margin: 0 auto;
}

.newsletter-form input {
    flex: 1;
    padding: 0.75rem 1rem;
    border: none;
    border-radius: var(--radius-md);
    font-size: 1rem;
}

.newsletter-form input::placeholder {
    color: var(--color-text-light);
}

/* Footer */
.footer {
    background-color: var(--color-primary);
    color: white;
    padding: var(--spacing-xl) var(--spacing-lg) var(--spacing-lg);
}

.footer-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: var(--spacing-lg);
    margin-bottom: var(--spacing-lg);
}

.footer-section h4 {
    margin-bottom: var(--spacing-sm);
    font-weight: 700;
}

.footer-section ul {
    list-style: none;
}

.footer-section li {
    margin-bottom: 0.5rem;
}

.footer-section a {
    color: rgba(255, 255, 255, 0.7);
    text-decoration: none;
    transition: var(--transition);
    font-size: 0.95rem;
}

.footer-section a:hover {
    color: var(--color-accent);
}

.social-links {
    display: flex;
    gap: var(--spacing-md);
}

.footer-bottom {
    text-align: center;
    padding-top: var(--spacing-lg);
    border-top: 1px solid rgba(255, 255, 255, 0.1);
    color: rgba(255, 255, 255, 0.6);
    font-size: 0.9rem;
}

/* Responsive Design */
@media (max-width: 768px) {
    .container {
        padding: 0 var(--spacing-md);
    }

    .hero-title {
        font-size: 2rem;
    }

    .hero-subtitle {
        font-size: 1rem;
    }

    .section-title {
        font-size: 1.75rem;
    }

    .products-grid {
        grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    }

    .deals-grid,
    .editorial-grid {
        grid-template-columns: 1fr;
    }

    .nav {
        display: none;
    }

    .newsletter-form {
        flex-direction: column;
    }

    .nav-link::after {
        display: none;
    }
}

@media (max-width: 480px) {
    .hero {
        padding: 3rem var(--spacing-md);
    }

    .hero-title {
        font-size: 1.5rem;
    }

    .featured-section,
    .deals-section,
    .editorial-section,
    .newsletter-section {
        padding: var(--spacing-lg) var(--spacing-md);
    }

    .section-title {
        font-size: 1.5rem;
        margin-bottom: var(--spacing-lg);
    }

    .products-grid {
        gap: var(--spacing-md);
    }

    .product-card {
        border: none;
        box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
    }

    .btn {
        width: 100%;
    }

    .header-content {
        padding: var(--spacing-sm) 0;
    }

    .header-actions {
        gap: var(--spacing-sm);
    }

    .footer-grid {
        grid-template-columns: 1fr;
        gap: var(--spacing-md);
    }
}

